import sys
from math import gcd
def main():
    data = sys.stdin.read().split()
    N, k = int(data[0]), int(data[1])
    a = sorted(set(int(x) for x in data[2:2 + k]))
    b = []
    for x in a:
        if x <= N and all(x % y for y in b):
            b.append(x)
    terms = []
    for x in b:
        new = [(x, 1)]
        for l, s in terms:
            L = l // gcd(l, x) * x
            if L <= N:
                new.append((L, -s))
        terms += new
    print(sum(s * (N // l) for l, s in terms))
main()

import sys
from math import gcd
def factor(n):
    f = {}
    p = 2
    while p * p <= n:
        while n % p == 0:
            f[p] = f.get(p, 0) + 1
            n //= p
        p += 1 if p == 2 else 2
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f
def solve(m):
    f = factor(m)
    ok = m in (2, 4) or (len(f) == 1 and 2 not in f) or (len(f) == 2 and f.get(2) == 1)
    if not ok:
        return -1
    phi = 1
    for p, e in f.items():
        phi *= p ** (e - 1) * (p - 1)
    qs = list(factor(phi).keys())
    g = 1
    while True:
        if gcd(g, m) == 1 and all(pow(g, phi // q, m) != 1 for q in qs):
            return g
        g += 1
def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    print("\n".join(str(solve(int(x))) for x in data[1:1 + t]))
main()

